    fun getAdviceForCategory(category: String, likedTitles: List<String> = emptyList()): List<AdviceItem> {
        val matches = adviceList.filter { it.category.equals(category, ignoreCase = true) }
        return if (matches.isNotEmpty()) matches.shuffled().sortedByDescending { likedTitles.contains(it.title) }.take(4) 
        else adviceList.shuffled().take(4) // Fallback to random
    }
